// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e18);
        Attacker a = new Attacker(c);
        vm.deal(address(a), amount);
        a.deposit{value: amount}();
        bool ok;
        try a.attack() { ok = true; } catch { ok = false; }
        // Rule: a successful withdraw must have drained the contract's ETH.
        assertTrue(!ok || address(c).balance == 0);
    }
}

contract Attacker {
    keepMyEther c;
    constructor(keepMyEther _c) { c = _c; }
    function deposit() external payable {
        (bool s, ) = address(c).call{value: msg.value}("");
        require(s);
    }
    function attack() external { c.withdraw(); }
    fallback() external payable { revert(); }
}
